"""Build an Unreal target using the source substitutions generated by ModHeaderTool."""

from __future__ import annotations

import argparse
import platform as host_platform
import hashlib
import json
import os
import re
import subprocess
import sys
import tempfile
from contextlib import contextmanager
from pathlib import Path


def read_json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def digest(path: Path) -> str:
    with path.open("rb") as stream:
        result = hashlib.sha256()
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            result.update(block)
        return result.hexdigest()


@contextmanager
def build_lock(path: Path):
    with path.open("a+b") as stream:
        stream.seek(0)
        try:
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(stream.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl

                fcntl.flock(stream, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError as error:
            raise ValueError(f"Another Hook build is active for {path.parent}") from error
        yield  # Both kinds of lock are released when the file is closed.


def split_arguments(command: str) -> list[str]:
    """Read the double-quoted argument string used by UBT ProcessStartInfo on all hosts."""
    result = []
    word = []
    quoted = started = False
    slashes = 0
    skip_next_quote = False
    for index, char in enumerate(command + " "):
        if skip_next_quote:
            skip_next_quote = False
            continue
        if char == "\\":
            slashes += 1
            started = True
            continue
        if char == '"':
            word.append("\\" * (slashes // 2))
            if slashes % 2:
                word.append('"')
            elif quoted and command[index + 1 : index + 2] == '"':
                word.append('"')
                skip_next_quote = True
            else:
                quoted = not quoted
            started = True
        else:
            word.append("\\" * slashes)
            if not quoted and char.isspace():
                if started:
                    result.append("".join(word))
                word.clear()
                started = False
            else:
                word.append(char)
                started = True
        slashes = 0
    if quoted:
        raise ValueError("Unterminated quoted UBT argument")
    return result


def split_gnu_response(content: str) -> list[str]:
    words = []
    word = []
    quote = None
    characters = iter(content)
    for char in characters:
        if char == "\\":
            word.append(next(characters, "\\"))
        elif quote:
            if char == quote:
                quote = None
            else:
                word.append(char)
        elif char in ("'", '"'):
            quote = char
        elif char.isspace():
            if word:
                words.append("".join(word))
                word.clear()
        else:
            word.append(char)
    if quote:
        raise ValueError("Unterminated quote in compiler response file")
    if word:
        words.append("".join(word))
    return words


def replace_source(
    arguments: list[str], working: Path, copies: dict[Path, Path], scratch: Path, msvc: bool, depth: int = 0
) -> tuple[list[str], list[Path]]:
    if depth > 16:
        raise ValueError("UBT response file nesting is too deep")
    rewritten = []
    matches = []
    for arg in arguments:
        if arg.startswith("@"):
            response = (working / arg[1:]).resolve()
            data = response.read_bytes()
            encoding = (
                "utf-16"
                if data.startswith((b"\xff\xfe", b"\xfe\xff"))
                else "utf-8-sig"
                if data.startswith(b"\xef\xbb\xbf")
                else "utf-8"
            )
            content = data.decode(encoding)
            tokens = split_arguments(content) if msvc else split_gnu_response(content)
            tokens, found = replace_source(tokens, working, copies, scratch, msvc, depth + 1)
            if found:
                name = hashlib.sha256(os.fsencode(response)).hexdigest() + ".rsp"
                copy = scratch / name
                # LLVM's GNU response parser accepts double quotes with escaped backslashes/quotes.
                content = (
                    subprocess.list2cmdline(tokens)
                    if msvc
                    else "\n".join(
                        '"' + token.replace("\\", "\\\\").replace('"', '\\"') + '"' for token in tokens
                    )
                )
                copy.write_bytes((content + "\n").encode(encoding))
                matches.extend(found)
                arg = "@" + str(copy)
        elif arg.lower().endswith((".cpp", ".cc", ".cxx")):
            prefix = arg[:3] if arg.startswith(("/Tp", "/Tc")) else ""
            source = (working / arg[len(prefix) :]).resolve()
            if source in copies:
                matches.append(source)
                arg = prefix + str(copies[source])
        rewritten.append(arg)
    return rewritten, matches


def load_sources(
    generated: Path, game: str, target: str, configuration: str, platform: str, architecture: str
) -> dict[Path, dict]:
    manifest = read_json(generated / f"{game}.generated-artifacts.json")
    identity = tuple(
        manifest[key] for key in ("status", "target", "configuration", "platform", "architecture")
    )
    if identity != ("Complete", target, configuration, platform, architecture) or manifest["format"] not in (
        "UMF.GeneratedArtifacts",
        "UMF.UbtHostArtifacts",
    ):
        raise ValueError("The MHT generation does not match this target")
    entries = {entry["path"]: entry["contentHash"] for entry in manifest["generatedFiles"]}
    map_name = "Diagnostics/HookSources.json"
    if map_name not in entries:
        return {}
    map_path = generated / map_name
    if digest(map_path) != entries[map_name]:
        raise ValueError("The MHT Hook source map changed after generation")
    source_map = read_json(map_path)
    if (source_map["format"], source_map["schemaVersion"]) != ("UMF.HookSourceMap", 1):
        raise ValueError("Invalid MHT Hook source map")
    units = {}
    for unit in source_map["units"]:
        source = Path(unit["source"]).resolve(strict=True)
        copy = (generated / unit["generated"]).resolve(strict=True)
        if (
            source in units
            or not copy.is_relative_to(generated / "Diagnostics/HookSources")
            or digest(source) != unit["sourceHash"]
            or digest(copy) != unit["generatedHash"]
            or entries.get(unit["generated"]) != unit["generatedHash"]
        ):
            raise ValueError(f"Invalid or stale Hook source substitution for {source}")
        units[source] = {**unit, "copy": copy}
    return units


def patch_actions(graph: dict, units: dict[Path, dict], scratch: Path) -> dict[Path, Path]:
    objects = {}
    if not units:
        return objects
    copies = {source: unit["copy"] for source, unit in units.items()}
    for action in graph["Actions"]:
        if action["Type"] != "Compile":
            continue
        args, matches = replace_source(
            split_arguments(action["CommandArguments"]),
            Path(action["WorkingDirectory"]),
            copies,
            scratch,
            Path(action["CommandPath"]).stem.lower() in ("cl", "cl-filter", "clang-cl"),
        )
        if not matches:
            continue
        if len(matches) != 1 or matches[0] in objects:
            raise ValueError("Each rewritten Hook source requires one non-unity compile action")
        source = matches[0]
        outputs = [Path(item) for item in action["ProducedItems"] if item.lower().endswith((".obj", ".o"))]
        if len(outputs) != 1:
            raise ValueError(f"Expected one object output for {source}")
        objects[source] = outputs[0]
        action["CommandArguments"] = subprocess.list2cmdline(args)
        action["CommandVersion"] += " HookSource=" + units[source]["generatedHash"]
        action["bCanExecuteRemotely"] = False
        action["bCanExecuteInUBA"] = False
        print(f"Compiling Hook source {source.name} from {copies[source]}", flush=True)
    return objects


def restore_action_dependencies(graph: dict) -> None:
    # UE 5.6 exports predecessor IDs, but ExecuteMode links imported actions by file dependencies.
    actions = {action["Id"]: action for action in graph["Actions"]}
    for action in actions.values():
        prerequisites = dict.fromkeys(action.get("PrerequisiteItems", []))
        for predecessor in action["PrerequisiteActions"]:
            outputs = actions[predecessor]["ProducedItems"]
            if not outputs:
                raise ValueError(f"UBT action {predecessor} has a dependent action and no file outputs")
            prerequisites.update(dict.fromkeys(outputs))
        action["PrerequisiteItems"] = list(prerequisites)


def native_host() -> tuple[str, str, str]:
    host = {"win32": ("Win64", "win"), "linux": ("Linux", "linux"), "darwin": ("Mac", "mac")}.get(
        sys.platform
    )
    if not host:
        raise ValueError(f"Unrecognized UBT build host: {sys.platform}")
    machine = host_platform.machine().lower()
    arch = {"amd64": "x64", "x86_64": "x64", "aarch64": "arm64", "arm64": "arm64"}.get(machine)
    if not arch:
        raise ValueError(f"Unrecognized build host architecture: {machine}")
    return ("LinuxArm64" if host[0] == "Linux" and arch == "arm64" else host[0]), host[1], arch


def build(
    engine: Path,
    project: Path,
    target: str,
    configuration: str,
    platform: str,
    architecture: str,
    jobs: int,
    force: bool,
    rebuild: bool,
) -> None:
    if engine.name.casefold() != "engine":
        engine /= "Engine"
    ubt = engine / "Binaries/DotNET/UnrealBuildTool/UnrealBuildTool.dll"
    _, system, host_arch = native_host()
    binary = "dotnet.exe" if system == "win" else "dotnet"
    runtimes = engine / "Binaries/ThirdParty/DotNet"
    dotnets = sorted(runtimes.glob(f"*/{system}-{host_arch}/{binary}"))
    if not dotnets and system == "win" and host_arch == "arm64":
        dotnets = sorted(runtimes.glob("*/win-x64/dotnet.exe"))
    if not ubt.is_file() or not dotnets:
        raise ValueError(f"Missing UBT or bundled .NET for {system}-{host_arch} under {engine}")
    command = [str(dotnets[-1]), str(ubt)]
    target_args = [
        target,
        platform,
        configuration,
        f"-Architecture={architecture}",
        f"-Project={project}",
        "-WaitMutex",
        f"-MaxParallelActions={jobs}",
    ]
    root = project.parent
    variant = Path(target) / platform / configuration / architecture
    generated = root / "Intermediate/ModTools/ModHeaderTool/Generated" / variant
    work = root / "Intermediate/ModTools/HookBuild" / variant
    work.mkdir(parents=True, exist_ok=True)
    receipt = work / "objects.json"
    with (
        build_lock(work / ".build.lock"),
        tempfile.TemporaryDirectory(prefix="actions-", dir=work, ignore_cleanup_errors=True) as directory,
    ):
        game = read_json(root / "Config/ModHeaderTool.json")["generation"]["gameId"]
        previous = read_json(receipt) if receipt.is_file() else {}
        scratch = Path(directory).resolve()
        if scratch.parent != work.resolve():
            raise ValueError("Unexpected Hook build scratch directory")
        actions_file = scratch / "Actions.json"
        export = target_args + ["-NoHotReloadFromIDE", f"-WriteOutdatedActions={actions_file}"]
        if force:
            export.append("-ForceHeaderGeneration")
        if rebuild:
            export.append("-Rebuild")
        subprocess.run(command + export, cwd=engine / "Source", check=True)
        units = load_sources(generated, game, target, configuration, platform, architecture)
        graph = read_json(actions_file)
        restore_action_dependencies(graph)
        objects = patch_actions(graph, units, scratch)
        for source, unit in units.items():
            if source in objects:
                continue
            cached = previous.get(str(source), {})
            obj = Path(cached.get("object", ""))
            if (
                cached.get("generatedHash") != unit["generatedHash"]
                or not obj.is_file()
                or digest(obj) != cached.get("objectHash")
            ):
                raise ValueError(
                    f"UBT omitted a required Hook compile for {source}. Run this driver with --rebuild"
                )
            objects[source] = obj
        actions_file.write_text(json.dumps(graph, indent=2), encoding="utf-8")
        if graph["Actions"]:
            subprocess.run(
                command + ["-Mode=Execute", f"-Actions={actions_file}", "-NoUBA", *target_args],
                cwd=engine / "Source",
                check=True,
            )
        if load_sources(generated, game, target, configuration, platform, architecture) != units:
            raise ValueError("The Hook source map changed while the build was running")
        audit = {
            str(source): {
                "generatedHash": units[source]["generatedHash"],
                "object": str(obj),
                "objectHash": digest(obj),
            }
            for source, obj in objects.items()
        }
        completed = scratch / "objects.json"
        completed.write_text(json.dumps(audit, indent=2) + "\n", encoding="utf-8")
        completed.replace(receipt)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--engine", type=Path, required=True)
    parser.add_argument(
        "--project",
        type=Path,
        default=Path(__file__).resolve().parents[1] / "UnrealModFramework/UnrealModFrameworkDev.uproject",
    )
    parser.add_argument("--platform", help="UBT target platform; defaults to the build host")
    parser.add_argument("--architecture", help="one UBT target architecture, e.g. x64 or arm64")
    parser.add_argument("--target", help="UE target name")
    parser.add_argument("--configuration", default="Development")
    parser.add_argument("--jobs", type=int, default=6)
    parser.add_argument("--force-header-generation", action="store_true")
    parser.add_argument(
        "--rebuild", action="store_true", help="clean the selected target before exporting actions"
    )
    args = parser.parse_args()
    try:
        host, _, host_arch = native_host()
        platform = args.platform or host
        arch = args.architecture
        if arch is None:
            arch = (
                host_arch
                if platform == host
                else {
                    "Linux": "x64",
                    "LinuxArm64": "arm64",
                    "Win64": "x64",
                    "Mac": "arm64",
                    "Android": "arm64",
                    "IOS": "arm64",
                    "TVOS": "arm64",
                    "VisionOS": "arm64",
                }.get(platform)
            )
        if not arch:
            parser.error("Supply --architecture for this UBT target platform")
        target = args.target or (
            "UnrealModFrameworkDevEditor"
            if platform in ("Win64", "Linux", "LinuxArm64", "Mac")
            else "UnrealModFrameworkDev"
        )
        if (
            not all(
                re.fullmatch(r"[A-Za-z0-9_]+", name) for name in (target, platform, arch, args.configuration)
            )
            or args.jobs < 1
        ):
            parser.error("Supply valid UE target identifiers and a positive job count")
        build(
            args.engine.resolve(strict=True),
            args.project.resolve(strict=True),
            target,
            args.configuration,
            platform,
            arch,
            args.jobs,
            args.force_header_generation,
            args.rebuild,
        )
    except (KeyError, OSError, ValueError, subprocess.CalledProcessError) as error:
        print(f"Hook build: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
